function esc(v){
  return String(v ?? '').replace(/[&<>"']/g, m => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[m]));
}
function rowsFor(m){ return DATA[m] || []; }
function studyRows(m){ return rowsFor(m).filter(r => r[4]); }
function weekNo(r){ return Number(String(r?.[0] || '').match(/(\d+)/)?.[1] || 0); }
function localToday(){
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
const WEEK_STARTS = rowsFor('סנהדרין').map((_,i) => {
  const d = new Date(Date.UTC(2026,9,11+i*7));
  return d.toISOString().slice(0,10);
});
function currentWeekIndex(){
  const t = localToday();
  let i = 0;
  WEEK_STARTS.forEach((d,n)=>{ if(d <= t) i=n; });
  return Math.max(0, Math.min(i, WEEK_STARTS.length-1));
}
let currentIndex = currentWeekIndex();

function setNav(v){
  document.querySelectorAll('.navbtn').forEach(b => b.classList.toggle('active', b.dataset.view === v));
}
async function go(v){
  const el = document.getElementById(v);
  if(!el) return;
  document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));
  el.classList.add('active');
  setNav(v);
  try{
    if(v==='home') renderHome();
    if(v==='plan') renderPlan();
    if(v==='personal') await renderPersonal();
    if(v==='tools') await renderTools();
    if(v==='cards') await renderCards();
    if(v==='admin') await renderAdmin();
    window.scrollTo({top:0,behavior:'smooth'});
  }catch(e){
    console.error(e);
    el.innerHTML = `<div class="card error">אירעה שגיאה.<br><small>${esc(e.message || 'לא ניתן לטעון את הנתונים')}</small></div>`;
  }
}
function bindNavigation(){
  document.querySelectorAll('.navbtn').forEach(b => b.onclick=()=>go(b.dataset.view));
}

function weekCard(w,m){
  if(!w) return `<div class="card">אין נתוני תכנית.</div>`;
  return `<article class="card current-week">
    <div class="week-top"><span class="badge">${w[4]?'השבוע הנוכחי':'בין הזמנים / ללא לימוד'}</span><strong>${esc(w[0])}</strong></div>
    <div class="week-subject"><span>${esc(m)}</span><span>${esc(w[5]||'—')}</span></div>
    <h2>${esc(w[4]||'אין הספק לימוד השבוע')}</h2>
    <div class="week-meta">${esc(w[1])} · פרשת ${esc(w[2]||'—')}</div>
    <div class="week-tools">
      <button class="tool-mini" onclick="go('tools')">📚 סיכומים</button>
      <button class="tool-mini" onclick="go('tools')">📊 טבלאות</button>
      <button class="tool-mini" onclick="toolsMasechet='${esc(m)}';toolsType='flashcards';go('cards')">🃏 כרטיסיות</button>
    </div>
  </article>`;
}
