async function progressMap(m,uid=user?.id){
  if(!sb || !uid) return new Map();
  const {data,error}=await sb.from('kch_weekly_progress').select('week_no,status').eq('user_id',uid).eq('masechet',m);
  if(error) throw error;
  return new Map((data||[]).map(x=>[Number(x.week_no),x.status]));
}
function weighted(rows,map){
  if(!rows.length) return 0;
  let n=0;
  rows.forEach(r=>{
    const s=map.get(weekNo(r))||'not_started';
    n += s==='completed' ? 1 : s==='partial' ? .5 : 0;
  });
  return Math.round(n/rows.length*100);
}
async function renderPlanCharts(m,study){
  if(!user) return;
  const map=await progressMap(m), pct=weighted(study,map);
  const done=study.filter(r=>map.get(weekNo(r))==='completed').length;
  document.getElementById('generalChart').innerHTML=
    `<div class="big-percent">${pct}%</div><div class="bar"><i style="width:${pct}%"></i></div>
     <div class="meta">${done} מתוך ${study.length} שבועות הושלמו</div>`;
  const groups={};
  study.forEach(r=>(groups[r[5]||'ללא פרק']??=[]).push(r));
  document.getElementById('perekChart').className='';
  document.getElementById('perekChart').innerHTML=Object.entries(groups).map(([p,a])=>{
    const x=weighted(a,map);
    return `<div class="perek-line"><div><b>${esc(p)}</b><span>${x}%</span></div>
      <div class="bar small"><i style="width:${x}%"></i></div><small>${a.length} שבועות</small></div>`;
  }).join('');
}

