  const byM={};Object.keys(MASECHTOT).forEach(m=>{let sc=0,total=0;ids.forEach(uid=>studyRows(m).forEach(r=>{total++;const st=pm.get(uid+'|'+m+'|'+weekNo(r));if(st==='completed')sc++;else if(st==='partial')sc+=.5}));byM[m]=total?Math.round(sc/total*100):0});
